import os
import pty
import select
import signal
import struct
import time

try:
    import fcntl
    import termios

    _HAS_TERMIOS = True
except ImportError:  # pragma: no cover - non-unix fallback
    _HAS_TERMIOS = False

import pyte

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    """A headless terminal backed by a real PTY running an interactive bash shell.

    Keystrokes (including control characters and escape sequences) are written
    to the PTY master.  Output from the shell is fed through a ``pyte`` screen
    emulator so the visible terminal contents can be inspected at any time via
    :meth:`get_screen` / :meth:`get_screen_text`.
    """

    def __init__(self, cols: int = 80, rows: int = 24, shell: str | None = None):
        self.cols = cols
        self.rows = rows

        self._screen = pyte.Screen(cols, rows)
        self._stream = pyte.ByteStream(self._screen)

        self.pid, self._master_fd = pty.fork()
        if self.pid == 0:  # child process
            # Ensure a sane terminal environment for interactive programs.
            os.environ.setdefault("TERM", "xterm-256color")
            os.environ["COLUMNS"] = str(cols)
            os.environ["LINES"] = str(rows)
            shell_path = shell or os.environ.get("SHELL") or "/bin/bash"
            try:
                # -i : interactive (so ~/.bashrc etc. are sourced)
                os.execvp(shell_path, [shell_path, "-i"])
            except FileNotFoundError:
                os.execvp("/bin/sh", ["/bin/sh", "-i"])
            os._exit(1)

        # parent process
        self._set_winsize(rows, cols)
        # Give the shell a moment to start up and source startup files.
        self._drain(0.5)

    # ------------------------------------------------------------------
    # Low level helpers
    # ------------------------------------------------------------------
    def _set_winsize(self, rows: int, cols: int) -> None:
        if not _HAS_TERMIOS:
            return
        try:
            winsize = struct.pack("HHHH", rows, cols, 0, 0)
            fcntl.ioctl(self._master_fd, termios.TIOCSWINSZ, winsize)
        except OSError:
            pass

    def _drain(self, wait_sec: float) -> None:
        """Read available output for up to ``wait_sec`` seconds, feeding pyte."""
        deadline = time.monotonic() + max(wait_sec, 0.0)
        while True:
            remaining = deadline - time.monotonic()
            if remaining < 0:
                remaining = 0
            try:
                rlist, _, _ = select.select([self._master_fd], [], [], remaining)
            except (OSError, ValueError):
                break
            if self._master_fd in rlist:
                try:
                    data = os.read(self._master_fd, 65536)
                except OSError:
                    break
                if not data:
                    break
                self._stream.feed(data)
                # keep looping to consume any more immediately-available output
                continue
            # nothing ready within the remaining window
            if time.monotonic() >= deadline:
                break

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """Send raw keystrokes to the terminal.

        ``keystrokes`` is written verbatim to the PTY, so control characters
        such as ``"\\x03"`` (Ctrl-C) and escape sequences work as expected.
        Newlines act as pressing Enter.  After sending, output is consumed for
        ``wait_sec`` seconds.
        """
        data = keystrokes.encode("utf-8", errors="surrogateescape")
        while data:
            try:
                n = os.write(self._master_fd, data)
            except OSError:
                break
            data = data[n:]
        self._drain(wait_sec)

    def read(self, wait_sec: float = 0.1) -> None:
        """Consume any pending output without sending anything."""
        self._drain(wait_sec)

    def get_screen(self) -> list[str]:
        """Return the current visible screen as a list of row strings."""
        self._drain(0.0)
        return self._screen.display

    def get_screen_text(self) -> str:
        """Return the current visible screen as a single newline-joined string."""
        return "\n".join(self.get_screen())

    def close(self) -> None:
        """Terminate the shell and release the PTY."""
        try:
            os.close(self._master_fd)
        except OSError:
            pass
        if getattr(self, "pid", None):
            try:
                os.kill(self.pid, signal.SIGKILL)
            except OSError:
                pass
            try:
                os.waitpid(self.pid, 0)
            except OSError:
                pass
            self.pid = None

    def __enter__(self) -> "HeadlessTerminal":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass

